// Make failures visible: logs workflow, node and message. Extend with an Email/Slack node for alerts.
const e = $input.first().json;
const text = '[LendLoop ERROR] workflow=' + (e.workflow && e.workflow.name) + ' node=' + (e.execution && e.execution.lastNodeExecuted) + ' message=' + (e.execution && e.execution.error && e.execution.error.message);
console.error(text);
return [{ json: { alert: text } }];
